questionvariables.text:
eqn:f(x)=a^x;
f_domain:oo(-inf,inf);
f_range(a) :=
    if a > 1 then
        (oo(0,inf))
    elseif a < 1 then
         (oo(0,inf))
    else
        (" {1}");

f_range(2);  
ta_1:eqn;
ta_2:f_domain;
ta_3:f_range(2);


/*Initial value of slider a*/
a1: 1;
b1:0.5;


/*Correct values of a-base any value a>1 */
a_cor: 2.1;
/*Correct values of a-base any value a=1 */
b_cor:1;
/*Correct values of a-base any value 0<a<1 */
c_cor:0.5;
